import math, random
from air_quality.warning import alert_level_runs, level_probability
random.seed(0)
K, N = 12, 4
values = [[random.uniform(0, 5) for _ in range(N)] for _ in range(K)]
unc = [[random.uniform(0, 0.5) for _ in range(N)] for _ in range(K)]
pop = [1.0, 2.0, 1.5, 0.5]
beta, thr, m = 0.3, [1.0, 2.0, 3.0], 2
q, first, cum, exp = alert_level_runs(values, unc, pop, beta, thr, m)
probs, _, _ = level_probability(values, unc, pop, beta, thr)
refq = [[math.fsum(probs[t][j:]) for j in (1, 2, 3)] for t in range(K)]
for j in range(3):
    S = {(0,0): 1.0}
    rcum = []
    for t in range(K):
        qt = refq[t][j]
        contrib = {}
        for (r, c), ps in sorted(S.items()):
            contrib.setdefault((0,c), []).append(ps*(1-qt))
            if r < m:
                comp = r+1 == m
                key = (r+1, c+(1 if comp else 0))
            else:
                key = (r,c)
            contrib.setdefault(key, []).append(ps*qt)
        S = {k: math.fsum(v) for k, v in sorted(contrib.items())}
        rcum.append(math.fsum(p for (_,c),p in sorted(S.items()) if c>=1))
    for t in range(K):
        if not (0.0 <= cum[t][j] <= 1.0):
            print("range", j, t, cum[t][j])
        if t > 0 and cum[t][j] < cum[t-1][j]:
            print("mono", j, t, cum[t-1][j], cum[t][j])
        if cum[t][j] != rcum[t]:
            print("ref", j, t, repr(cum[t][j]), repr(rcum[t]))
